let blogshammirHeroSlider = function (e) { let o = e.querySelector(".blogshammir-spinner"), t = function () { o.classList.remove("visible"), setTimeout((function () { o.style.display = "none" }), 300), e.classList.add("loaded") }; return imagesLoaded(e, (function () { document.getElementById("blogshammir-preloader") && !document.body.classList.contains("blogshammir-loaded") ? document.body.addEventListener("blogshammir-preloader-done", (function () { setTimeout(t, 300) })) : setTimeout(t, 300) })), e }; window.blogshammirHeroSlider = blogshammirHeroSlider, document.addEventListener("DOMContentLoaded", (function () { document.querySelectorAll(".blogshammir-hero-slider").forEach((e => { blogshammirHeroSlider(e) })) }));
